/* screens.c - drawing whole screens from the converted art.
 *
 * The art is generated by tools/convert.py (see build/art.h) and lives in
 * the switchable banks, so each function switches to the right bank before
 * reading it. Background tiles go in the first pattern table ($0000),
 * sprite tiles in the second ($1000); PPU_CTRL tells the chip which is which. */

#include "art.h"
#include "map.h"
#include "mmc1.h"
#include "ppu.h"
#include "screens.h"

/* The sprite list (OAM, "object attribute memory"): 64 sprites x 4 bytes, at
 * $0200 in RAM. The vblank handler copies it to the graphics chip every frame.
 * Each sprite: Y position minus 1, tile number, attributes (bits 0-1:
 * palette), X position. */
#define OAM ((unsigned char *)0x0200)

/* Move every sprite below the bottom of the screen, which hides it. */
static void hide_sprites(void) {
    unsigned char i = 0;
    do {
        OAM[i] = 0xFF;
        i += 4;
    } while (i != 0);    /* i wraps from 252 back to 0 after the 64th sprite */
}

void show_overworld(unsigned char player, unsigned char cam_x, unsigned char cam_y) {
    const unsigned char *squares;
    const Sprite *p;
    unsigned char x, y, square, i;

    mmc1_set_bank(TERRAIN_BANK);
    ppu_set_addr(PPU_TILES);
    ppu_write(terrain.tiles, terrain.tile_count * 16u);
    ppu_set_addr(PPU_PALETTES);
    ppu_write(terrain.palettes, 16);

    /* The nametable, one tile at a time, row by row. Tile (x, y) on screen is
     * in map square (cam_x + x / 4, cam_y + y / 4), at position (x % 4, y % 4)
     * inside it. With powers of two, dividing is shifting right and the
     * remainder is masking off the low bits: x >> 2 and x & 3. Much cheaper
     * than / and % on a 6502. */
    squares = terrain.squares;
    ppu_set_addr(PPU_NAMETABLE0);
    for (y = 0; y < 30; ++y) {
        for (x = 0; x < 32; ++x) {
            square = map[cam_y + (y >> 2)][cam_x + (x >> 2)];
            PPU_DATA = squares[(square << 4) | ((y & 3) << 2) | (x & 3)];
        }
    }

    /* A square is exactly one 32x32 attribute block, so each square's
     * palettes come as one ready-made byte. */
    for (y = 0; y < 8; ++y) {
        for (x = 0; x < 8; ++x) {
            PPU_DATA = terrain.square_attributes[map[cam_y + y][cam_x + x]];
        }
    }

    /* The player's tiles, palettes, and the tile and palette of each of its
     * 16 sprites. Their positions are set separately, by place_player(). */
    mmc1_set_bank(players_bank[player]);
    p = players[player];
    ppu_set_addr(PPU_SPRITE_TILES);
    ppu_write(p->tiles, p->tile_count * 16u);
    ppu_set_addr(PPU_SPRITE_PALETTES);
    ppu_write(p->palettes, 16);

    hide_sprites();
    for (i = 0; i < 16; ++i) {
        OAM[(i << 2) + 1] = p->tile_map[i];
        OAM[(i << 2) + 2] = p->sprite_palettes[i];
    }
}

void place_player(unsigned char x, unsigned char y) {
    unsigned char row, col, i = 0;
    for (row = 0; row < 32; row += 8) {
        for (col = 0; col < 32; col += 8) {
            OAM[i]     = y + row - 1;       /* the chip draws sprites a line late */
            OAM[i + 3] = x + col;
            i += 4;
        }
    }
}

void show_battle(unsigned char enemy) {
    const Battle *b;
    const unsigned char *map;
    unsigned char y;

    hide_sprites();

    /* The backdrop fills the whole screen... */
    mmc1_set_bank(BACKDROP_BANK);
    ppu_set_addr(PPU_TILES);
    ppu_write(backdrop.tiles, backdrop.tile_count * 16u);
    ppu_set_addr(PPU_NAMETABLE0);
    ppu_write(backdrop.nametable, 960);

    /* ...then the enemy's tiles go in after the backdrop's, and its 16x16-tile
     * area is written over the backdrop, one row of 16 tiles at a time. */
    mmc1_set_bank(battles_bank[enemy]);
    b = battles[enemy];
    ppu_set_addr(PPU_TILES + BACKDROP_TILES * 16u);
    ppu_write(b->tiles, b->tile_count * 16u);

    map = b->tile_map;
    for (y = 0; y < 16; ++y) {
        ppu_set_addr(PPU_NAMETABLE0 + (BATTLE_ENEMY_Y + y) * 32u + BATTLE_ENEMY_X);
        ppu_write(map, 16);
        map += 16;
    }

    ppu_set_addr(PPU_ATTRIBUTES);
    ppu_write(b->attributes, 64);
    ppu_set_addr(PPU_PALETTES);
    ppu_write(b->palettes, 16);
}
